#include <stdio.h>

int main() {
    int h, m, s;
    if (scanf("%d:%d:%d", &h, &m, &s) == 3) {
        if (h >= 0 && h <= 23 && m >= 0 && m <= 59 && s >= 0 && s <= 59) {
            printf("Valid\n");
        } else {
            printf("Not Valid\n");
        }
    }
    return 0;
}

